@kt.kernel
def k(x=kt.In(8, 64), b=kt.In(64), y=kt.Out(8, 64)):
    h = kt.buffer((8, 64), "f16", tile=(4, 8))
    kt.gt4(h, x)
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(1):
            r = c * 4 + t * 4
            kt.load(x[r : r + 4, :])
            kt.load(x[r : r + 4, :], gt4=True)
            kt.load(x[r : r + 1, :], gt4=True)
            kt.load(b[0:32], gt4=True)
            d = kt.load(h[r : r + 4, :])
            kt.store(y[r : r + 4, :], d)
